using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using ReFix.Shared;
namespace ReFix.Hub {
 internal sealed class LinksWindow:Window {
  readonly ThemeStore themes;readonly SharedSourceStore store;readonly Action changed;readonly Border frame,image;readonly ListBox folders,repositories;readonly TextBox folderInput,repoInput,catalogInput;SourceSnapshot snapshot;bool closed;
  internal LinksWindow(ThemeStore themes,Action sourcesChanged=null){this.themes=themes;changed=sourcesChanged;store=new SharedSourceStore(themes.Root);string profileError=null;try{snapshot=store.Read();}catch(Exception ex){snapshot=new SourceSnapshot(new string[0],new RepositorySource[0]);profileError=ex.Message;}Title="HUB ReFIX — ссылки и источники";WindowStyle=WindowStyle.None;AllowsTransparency=true;Background=Brushes.Transparent;Width=Math.Min(720,SystemParameters.WorkArea.Width);Height=Math.Min(760,SystemParameters.WorkArea.Height);MinWidth=520;MinHeight=560;ShowInTaskbar=false;WindowStartupLocation=WindowStartupLocation.CenterOwner;Ui.Styles(this);frame=new Border{Margin=new Thickness(16),Padding=new Thickness(22),BorderThickness=new Thickness(1)};Content=frame;var layers=new Grid();frame.Child=layers;image=new Border{IsHitTestVisible=false};layers.Children.Add(image);var shell=new DockPanel();layers.Children.Add(shell);var close=Ui.Button("Закрыть",Close,false);DockPanel.SetDock(close,Dock.Bottom);shell.Children.Add(close);var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};shell.Children.Add(scroll);var panel=new StackPanel();scroll.Content=panel;
   var heading=Ui.Text("Ссылки и источники",25,"Hub.Foreground");heading.MouseLeftButtonDown+=delegate{try{DragMove();}catch(InvalidOperationException){}};panel.Children.Add(heading);if(profileError!=null)panel.Children.Add(Ui.Text("Не удалось прочитать список источников: "+profileError,12,"Hub.Tertiary"));panel.Children.Add(Ui.Text("Папка HUB",14,"Hub.Foreground"));var path=new TextBox{Text=AppDomain.CurrentDomain.BaseDirectory,IsReadOnly=true,Margin=new Thickness(0,8,0,4)};panel.Children.Add(path);panel.Children.Add(Ui.Button("Открыть папку HUB",()=>Open(AppDomain.CurrentDomain.BaseDirectory),false));panel.Children.Add(Ui.Text("Основной репозиторий (постоянный)",14,"Hub.Foreground"));panel.Children.Add(new TextBox{Text=SharedSourceStore.OfficialRepository,IsReadOnly=true,Margin=new Thickness(0,8,0,4)});panel.Children.Add(Ui.Button("Открыть основной репозиторий",()=>Open(SharedSourceStore.OfficialRepository),false));
   panel.Children.Add(Ui.Text("Папки расширений",16,"Hub.Foreground"));folders=List();panel.Children.Add(folders);panel.Children.Add(Ui.Text("Полный путь к папке",12,"Hub.Muted"));folderInput=new TextBox{ToolTip="Полный путь к папке расширений",Margin=new Thickness(0,5,0,5)};panel.Children.Add(folderInput);var local=new WrapPanel();local.Children.Add(Ui.Button("Выбрать папку",ChooseFolder,false));local.Children.Add(Ui.Button("Добавить",()=>Change(()=>{snapshot=new SourceSnapshot(snapshot.Folders.Concat(new[]{folderInput.Text}),snapshot.Repositories);}),false));local.Children.Add(Ui.Button("Открыть",()=>{if(folders.SelectedItem!=null)Open((string)folders.SelectedItem);},false));local.Children.Add(Ui.Button("Удалить",()=>Change(()=>{snapshot=new SourceSnapshot(snapshot.Folders.Where(p=>p!=(string)folders.SelectedItem),snapshot.Repositories);}),false));panel.Children.Add(local);
   panel.Children.Add(Ui.Text("Git-репозитории расширений",16,"Hub.Foreground"));repositories=List();panel.Children.Add(repositories);panel.Children.Add(Ui.Text("HTTPS URL репозитория",12,"Hub.Muted"));repoInput=new TextBox{ToolTip="HTTPS URL Git-репозитория",Margin=new Thickness(0,5,0,5)};panel.Children.Add(repoInput);panel.Children.Add(Ui.Text("HTTPS URL catalog.json (необязательно)",12,"Hub.Muted"));catalogInput=new TextBox{ToolTip="Необязательно: HTTPS URL совместимого catalog.json",Margin=new Thickness(0,0,0,5)};panel.Children.Add(catalogInput);panel.Children.Add(Ui.Text("URL репозитория; ниже — необязательный URL catalog.json.\nПо умолчанию: catalog/catalog.json, ветка main, затем master.\nДобавляйте только источники, которым доверяете: пакеты содержат программы.",12,"Hub.Muted"));var remote=new WrapPanel();remote.Children.Add(Ui.Button("Добавить репозиторий",()=>Change(()=>{snapshot=new SourceSnapshot(snapshot.Folders,snapshot.Repositories.Concat(new[]{new RepositorySource(repoInput.Text,catalogInput.Text)}));}),false));remote.Children.Add(Ui.Button("Открыть",()=>{var r=repositories.SelectedItem as RepositorySource;if(r!=null)Open(r.Repository);},false));remote.Children.Add(Ui.Button("Удалить",()=>Change(()=>{snapshot=new SourceSnapshot(snapshot.Folders,snapshot.Repositories.Where(r=>r!=(repositories.SelectedItem as RepositorySource)));}),false));panel.Children.Add(remote);
   themes.Changed+=ThemeChanged;Closed+=delegate{closed=true;themes.Changed-=ThemeChanged;};Apply();Refresh();
  }
  static ListBox List(){var list=new ListBox{Height=120,Margin=new Thickness(0,8,0,4)};VirtualizingStackPanel.SetIsVirtualizing(list,true);VirtualizingStackPanel.SetVirtualizationMode(list,VirtualizationMode.Recycling);ScrollViewer.SetCanContentScroll(list,true);return list;}
  void ChooseFolder(){using(var picker=new System.Windows.Forms.FolderBrowserDialog()){picker.Description="Папка расширений: catalog.json и packages или ZIP с module.json";if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)folderInput.Text=picker.SelectedPath;}}
  void Change(Action action){var previous=snapshot;try{action();store.Save(snapshot);Refresh();if(changed!=null)changed();}catch(Exception e){snapshot=previous;Refresh();MessageBox.Show(this,e.Message,"Источники",MessageBoxButton.OK,MessageBoxImage.Warning);}}
  void Refresh(){folders.ItemsSource=snapshot.Folders;repositories.ItemsSource=snapshot.Repositories;}
  void Open(string value){try{Process.Start(new ProcessStartInfo(value){UseShellExecute=true});}catch(Exception e){MessageBox.Show(this,e.Message,"Открыть",MessageBoxButton.OK,MessageBoxImage.Warning);}}
  void Apply(){Ui.Apply(this,themes.Current,frame,image,true);}
  void ThemeChanged(object sender,EventArgs e){if(!closed&&!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(delegate{if(!closed)Apply();}));}
 }
}
